CumulativeDistributionFunction.hasLaw_measure_iff.{u_1} (F : CumulativeDistributionFunction)
  {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {P : MeasureTheory.Measure Ω}
  [MeasureTheory.IsProbabilityMeasure P] {X : Ω → ℝ} (hX : AEMeasurable X P) :
  ProbabilityTheory.HasLaw X F.measure P ↔
    ∀ (x : ℝ), ↑F.toStieltjesFunction x = P.real {ω | X ω ≤ x}

ExtremeValueTheory.tendsto_measureReal_orderStat_le.{u_1} {Ω : Type u_1} [MeasurableSpace Ω]
  {P : MeasureTheory.Measure Ω} [MeasureTheory.IsProbabilityMeasure P] {X : ℕ → Ω → ℝ}
  (hX : ∀ (i : ℕ), Measurable (X i)) (hind : ProbabilityTheory.iIndepFun X P) {F : ℝ → ℝ}
  (hF : ∀ (i : ℕ) (x : ℝ), P.real {ω | X i ω ≤ x} = F x) {u : ℕ → ℝ} {τ : ℝ}
  (hu : Filter.Tendsto (fun n => ↑n * (1 - F (u n))) Filter.atTop (nhds τ)) (j : ℕ) :
  Filter.Tendsto (fun n => P.real {ω | ExtremeValueTheory.orderStat (fun i => X (↑i) ω) j ≤ u n})
    Filter.atTop (nhds (Real.exp (-τ) * ∑ m ∈ Finset.range (j + 1), τ ^ m / ↑m.factorial))
